import React, { useEffect, useState } from 'react';

function LifetimeWithdraw() {
  const [lifetimeWinning, setLifetimeWinning] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    fetch('/api/withdraw/lifetime', {
      method: 'GET',
      headers: {
        'Content-Type': 'application/json',
        // যদি টোকেন লাগে:
        // 'Authorization': `Bearer ${yourToken}`,
      },
    })
      .then(res => {
        if (!res.ok) throw new Error('Failed to fetch lifetime winning');
        return res.json();
      })
      .then(data => {
        setLifetimeWinning(data);
        setLoading(false);
      })
      .catch(err => {
        setError(err.message);
        setLoading(false);
      });
  }, []);

  if (loading) return <div>Loading...</div>;
  if (error) return <div>Error: {error}</div>;

  return (
    <div>
      <h2>Lifetime Winning</h2>
      <p>৳ {lifetimeWinning}</p>
    </div>
  );
}

export default LifetimeWithdraw;
